# Source for q/ae-anatphys3.js: Anatomy + Physiology third batch.
AN="Anatomy"; PH="Physiology"
Q=[
# --- Coronary anatomy ---
(AN,"The right coronary artery arises from the:","Right (anterior) aortic sinus",["Left sinus","Noncoronary sinus","Pulmonary trunk"],"The left main arises from the left sinus.","F"),
(AN,"Which aortic cusp lies next to the interatrial septum?","The noncoronary cusp",["The right coronary cusp","The left coronary cusp","None"],"This is why aortic root abscesses can extend toward the atria.","C"),
(AN,"The first branch of the RCA is usually the:","Conus branch",["Obtuse marginal","Diagonal","Ramus intermedius"],"The conus branch supplies the RV outflow tract.","C"),
(AN,"The sinoatrial (SA) node artery most often arises from the:","RCA (in about 60% of people)",["LAD","Left main","PDA"],"In the rest it arises from the LCx.","C"),
(AN,"The acute marginal branch supplies the:","RV free wall",["LV lateral wall","LV apex","LA"],"It comes from the RCA along the acute margin of the heart.","F"),
(AN,"Obtuse marginal branches come from the:","Left circumflex artery",["RCA","LAD","Conus artery"],"They supply the lateral LV wall.","F"),
(AN,"A ramus intermedius is:","A third branch from the left main, between the LAD and LCx",["A branch of the RCA","A vein","A normal branch of the PDA"],"It supplies the lateral wall when present.","C"),
(AN,"The LAD runs in the:","Anterior interventricular groove",["Posterior AV groove","Right AV groove","Posterior interventricular groove"],"The PDA runs in the posterior interventricular groove.","F"),
(AN,"The acute margin of the heart is formed mainly by the:","Right ventricle",["Left ventricle","Left atrium","Aorta"],"The obtuse margin is formed mainly by the LV.","F"),
# --- Valves and fibrous skeleton ---
(AN,"Aortomitral continuity means:","The anterior mitral leaflet is directly joined by fibrous tissue to the aortic valve",["The mitral and aortic valves share a muscle band","The aortic valve sits in the RV","The mitral valve is next to the pulmonic valve"],"On the right side, muscle (the infundibulum) separates the tricuspid and pulmonic valves.","F"),
(AN,"The septal tricuspid leaflet normally attaches:","Slightly closer to the apex than the anterior mitral leaflet",["Higher than the mitral leaflet","At the same level exactly","On the LV side"],"This offset helps identify the tricuspid valve and the RV.","F"),
(AN,"The triangle of Koch, in the RA, marks the location of the:","AV node",["SA node","Coronary sinus thrombus","Fossa ovalis"],"Its borders are the tendon of Todaro, the tricuspid septal leaflet and the coronary sinus opening.","C"),
(AN,"The bundle of His passes through the:","Central fibrous body to reach the ventricular septum",["Left atrial appendage","Pulmonary veins","Moderator band only"],"It then divides into the right and left bundle branches.","F"),
(AN,"The right bundle branch partly travels within the:","Moderator band",["Crista terminalis","Coronary sinus","Tendon of Todaro"],"This allows fast conduction to the anterior papillary muscle.","F"),
(AN,"Bachmann's bundle carries electrical signals:","From the right atrium to the left atrium",["From the AV node to the ventricles","Within the LV","Back to the SA node"],"It coordinates contraction of both atria.","C"),
(AN,"The Thebesian valve guards the opening of the:","Coronary sinus",["IVC","SVC","Pulmonary veins"],"The Eustachian valve guards the IVC.","F"),
(AN,"In the fetus, the Eustachian valve helps direct blood from the:","IVC across the foramen ovale into the LA",["SVC into the RV","Aorta to the PA","LV to the aorta"],"This sends oxygen-rich placental blood to the left heart and brain.","F"),
(AN,"Compared with the LV, normal RV trabeculations are:","Coarse",["Fine","Absent","Calcified"],"The LV has fine trabeculations, mostly at the apex.","F"),
(AN,"Normal RV free wall thickness in adults is under about:","5 mm",["15 mm","10 mm","2 cm"],"A thicker wall suggests RV pressure overload.","F"),
# --- Great vessels and surroundings ---
(AN,"The main pulmonary artery normally lies:","Anterior to and to the left of the aorta at the base",["Behind the aorta","To the right of the aorta","Below the LA"],"In d-TGA the arteries are parallel instead of crossing.","F"),
(AN,"The ligamentum arteriosum is the remnant of the:","Ductus arteriosus",["Foramen ovale","Ductus venosus","Umbilical artery"],"It connects the left pulmonary artery to the underside of the aortic arch.","F"),
(AN,"The left recurrent laryngeal nerve hooks around the:","Aortic arch near the ligamentum arteriosum",["Right subclavian artery","SVC","Pulmonary veins"],"A large LA or aortic aneurysm can compress it and cause hoarseness.","C"),
(AN,"The four pulmonary veins enter the:","Posterior wall of the left atrium",["Right atrium","Left atrial appendage","Anterior wall of the LA"],"The LAA lies anterolaterally.","F"),
(AN,"The most common shape of the left atrial appendage on imaging is:","'Chicken wing'",["'Cauliflower'","'Windsock'","'Cactus'"],"Cauliflower types have been linked with higher stroke risk.","C"),
(AN,"About how much of the heart lies to the left of the midline?","About two-thirds",["None","About one-tenth","All of it"],"The base faces back and to the right; the apex points forward and to the left.","F"),
(AN,"The sternocostal (front) surface of the heart is formed mainly by the:","Right ventricle",["Left atrium","Left ventricle only","Coronary sinus"],"The diaphragmatic surface is formed mainly by the LV and part of the RV.","F"),
(AN,"The base of the heart is formed mainly by the:","Left atrium",["Right ventricle","LV apex","Right atrium only"],"The base faces back, toward the spine.","F"),
(AN,"The left phrenic nerve runs over the:","Pericardium covering the LV",["Inside the LA","Inside the aorta","Under the RV"],"It can be injured during surgery or ablation.","C"),
(AN,"The ascending aorta in adults is about how long?","About 5 cm",["About 1 cm","About 20 cm","About 50 cm"],"It runs from the aortic root to the start of the arch.","C"),
(AN,"The LV papillary muscles each send chordae to:","Both mitral leaflets",["Only the anterior leaflet","Only the posterior leaflet","The tricuspid valve"],"Each muscle supports the half of both leaflets on its side.","C"),
(AN,"The heart's conduction tissue that spreads signals quickly through the ventricles is the:","Purkinje fiber network",["Bachmann's bundle","SA node","Crista terminalis"],"Fast conduction lets the ventricles contract together.","F"),
# --- Physiology: cell and electrical ---
(PH,"In ventricular muscle cells, phase 0 of the action potential is caused by:","Rapid sodium influx",["Potassium outflow","Calcium release from the SR only","Chloride influx"],"Phase 2 (plateau) depends on calcium influx; phase 3 on potassium outflow.","F"),
(PH,"The plateau phase (phase 2) of the ventricular action potential is maintained mainly by:","Calcium entering the cell",["Sodium leaving","Potassium entering","Chloride leaving"],"Calcium also triggers more calcium release from the sarcoplasmic reticulum.","F"),
(PH,"SA node cells generate spontaneous beats because of:","A slow inward current during phase 4 (the 'funny' current)",["A stable resting membrane","No ion channels","Fast sodium channels only"],"This gradual depolarization gives automaticity.","C"),
(PH,"Myocardial relaxation requires:","Energy (ATP) to pump calcium back into the sarcoplasmic reticulum",["No energy at all","Sodium entering the cell","Potassium release only"],"This is why ischemia impairs relaxation early.","F"),
(PH,"An 'inotropic' effect changes:","Contractility",["Heart rate","Conduction speed","Relaxation only"],"Chronotropic = rate; dromotropic = conduction speed; lusitropic = relaxation.","F"),
(PH,"Sympathetic stimulation through beta-1 receptors:","Raises heart rate, contractility and speed of relaxation",["Slows heart rate","Lowers contractility","Stops conduction"],"Parasympathetic (vagal) stimulation mainly slows the heart.","F"),
(PH,"The QT interval represents:","The whole time of ventricular depolarization and repolarization",["Atrial depolarization","AV node delay","Only ventricular repolarization"],"A long QT increases the risk of dangerous arrhythmias.","F"),
(PH,"The dicrotic notch on the aortic pressure trace marks:","Aortic valve closure",["Mitral valve opening","Atrial contraction","The start of ejection"],"It coincides with the second heart sound.","F"),
(PH,"The 'c' wave on the atrial pressure trace is caused by:","The tricuspid (or mitral) valve bulging back into the atrium in early systole",["Atrial contraction","Atrial filling","AV valve opening"],"The 'a' wave is atrial contraction; the 'v' wave is atrial filling.","C"),
(PH,"The 'y' descent on the atrial pressure trace reflects:","AV valve opening and rapid ventricular filling",["Atrial contraction","Atrial relaxation","Valve closure"],"A steep y descent is typical of constrictive pericarditis.","C"),
(PH,"The 'x' descent reflects:","Atrial relaxation and the descent of the AV valve ring in systole",["Ventricular filling","Atrial contraction","AV valve opening"],"The x descent is preserved in tamponade, while y is blunted.","C"),
# --- Physiology: pressures and flow ---
(PH,"Mean arterial pressure is roughly:","Diastolic pressure + one-third of the pulse pressure",["Systolic + diastolic","Systolic − diastolic","Half of systolic"],"For 120/80: 80 + 40 ÷ 3 ≈ 93 mmHg.","F"),
(PH,"A wide pulse pressure is typical of:","Chronic aortic regurgitation",["Aortic stenosis","Tamponade","Mitral stenosis"],"AS and tamponade usually narrow the pulse pressure.","F"),
(PH,"Systemic vascular resistance is calculated as:","(Mean arterial pressure − RA pressure) ÷ cardiac output",["Cardiac output ÷ MAP","Heart rate × stroke volume","PA pressure ÷ wedge pressure"],"Multiply by 80 to convert Wood units to dyn·s·cm⁻⁵.","C"),
(PH,"Pulmonary vascular resistance is calculated as:","(Mean PA pressure − wedge pressure) ÷ cardiac output",["(MAP − RA) ÷ CO","Heart rate ÷ CO","PASP − RVSP"],"Normal PVR is about 2 Wood units or less.","C"),
(PH,"Normal left atrial pressure (or wedge pressure) is about:","4 to 12 mmHg",["25 to 35 mmHg","0 mmHg always","50 mmHg"],"Higher values cause pulmonary congestion.","F"),
(PH,"The heart extracts about how much oxygen from coronary blood at rest?","About 70%",["About 10%","About 25%","Nearly none"],"Because extraction is already high, more demand must be met by more flow.","C"),
(PH,"Coronary blood flow at rest is about what share of cardiac output?","About 5%",["About 50%","About 25%","Under 1%"],"It can rise several-fold with exercise.","C"),
(PH,"When heart rate rises, which part of the cycle shortens most?","Diastole",["Systole","Both shorten equally","Neither"],"At high rates, mitral E and A waves may merge.","F"),
(PH,"Hypoxic pulmonary vasoconstriction means:","Lung arteries narrow in poorly ventilated areas, diverting blood to better areas",["Lung arteries widen with low oxygen","Systemic arteries narrow","Coronary arteries narrow"],"Widespread hypoxia can cause pulmonary hypertension.","F"),
(PH,"The pulmonary circulation compared with the systemic circulation has:","Low pressure and low resistance",["High pressure and high resistance","The same pressure","No resistance"],"The RV is thin-walled because it pumps against low resistance.","F"),
(PH,"Ejection fraction is described as 'load-dependent' because it:","Changes with preload and afterload, not just contractility",["Never changes","Depends only on heart rate","Depends only on BSA"],"In severe MR, a normal EF may hide reduced contractility.","C"),
(PH,"In severe MR, an EF of 60% may still mean reduced LV function because:","Part of each beat is ejected into the low-pressure LA",["MR raises afterload","EF measures MR directly","MR has no effect on EF"],"That is why surgery is advised when EF is 60% or less.","C"),
(PH,"The ejection phase of systole starts when:","LV pressure exceeds aortic pressure and the aortic valve opens",["The mitral valve opens","Atrial contraction begins","The T wave ends"],"It ends with aortic valve closure.","F"),
(PH,"At rest with a normal heart rate, the proportion of the cycle spent in diastole is about:","Two-thirds",["One-tenth","One-third","All of it"],"This shrinks with faster heart rates.","F"),
# --- Fetal and transitional ---
(PH,"In the fetus, the vessel carrying the most oxygen-rich blood is the:","Umbilical vein",["Umbilical artery","Pulmonary artery","Ductus arteriosus"],"It brings oxygenated blood from the placenta.","F"),
(PH,"The umbilical arteries carry:","Deoxygenated blood from the fetus to the placenta",["Oxygen-rich blood to the fetus","Blood to the lungs","Blood to the liver only"],"There are normally two umbilical arteries and one vein.","F"),
(PH,"In the fetus, pulmonary vascular resistance is:","High, so most RV output passes through the ductus to the aorta",["Low, so most blood flows to the lungs","The same as an adult","Zero"],"At birth, lung expansion lowers PVR sharply.","F"),
(PH,"The heart's own oxygen demand rises most with:","Higher heart rate, wall stress and contractility",["Lower heart rate","Lower blood pressure","Sleep"],"Beta-blockers lower demand by slowing the heart.","F"),
(PH,"The foramen ovale stays functionally closed after birth because:","LA pressure becomes higher than RA pressure",["RA pressure rises above LA","The ductus opens","PVR rises"],"A PFO can open if RA pressure rises, e.g. with Valsalva release.","F"),
]
